<?php require 'config.php';if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location:request.php');exit;}verify();$e=trim($_POST['email']??'');$n=trim($_POST['name']??'');$s=trim($_POST['subject']??'');$c=trim($_POST['category']??'Other');$p=$_POST['priority']??'normal';$m=trim($_POST['message']??'');if(!$n||!filter_var($e,FILTER_VALIDATE_EMAIL)||!$s||!$m||!in_array($p,['low','normal','high','urgent'],true))exit('Please complete the form.');$no=ticket_no();$q=db()->prepare("INSERT INTO tickets(ticket_no,name,email,subject,category,priority,message) VALUES(?,?,?,?,?,?,?)");$q->execute([$no,$n,$e,$s,$c,$p,$m]);header('Location:track.php?q='.urlencode($no));